update pages set contenu = '{"gabarit":"fiche","chapeau":"VOIT, spécialiste de la fabrication de pièces mécaniques de précision, a intégré un technicien Migen à temps plein sur son site en 2025. L''objectif posé : tenir la disponibilité de ses équipements critiques.","fiche":[],"contexte":"**Un centre d''usinage à grande vitesse arrêté, c''est une pièce de précision qui ne sort pas.** Et un client qui attend.\nDans l''environnement industriel de VOIT, la disponibilité des équipements est un enjeu quotidien. La maintenance devait tenir trois exigences en même temps :\n**Réactive** : Pour limiter les arrêts non planifiés.\n**Préventive** : Pour anticiper l''usure avant la casse.\n**Adaptée** : À des machines complexes, souvent multimarques.","intervention":"**Préventif et réglages sur les centres d''usinage** : Le technicien tient le plan d''entretien et les réglages sur les centres à grande vitesse.\n**Dépannage des presses** : Les presses hydrauliques comme mécaniques sont prises en charge sur place.\n**Diagnostic sur commandes numériques** : Les erreurs CN sont identifiées et corrigées sans attendre un intervenant extérieur.\n**Travail direct avec la production** : Le technicien collabore avec les équipes de production pour raccourcir les temps d''arrêt.\n**Supervision Migen** : Les coordinateurs Migen suivent la prestation tout au long de la mission.","resultats":[]}'::jsonb where path = '/preuves/voit-grand-est/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Client","valeur":"VOIT, pièces mécaniques de précision"},{"libelle":"Période","valeur":"2025"},{"libelle":"Besoin","valeur":"Renforcer les équipes de maintenance, tenir la disponibilité des équipements"},{"libelle":"Périmètre machines","valeur":"Centres d''usinage grande vitesse, presses automatisées, machines CN"},{"libelle":"Effectif Migen","valeur":"1 technicien de maintenance expérimenté, à temps plein"},{"libelle":"Suivi","valeur":"Supervision par les coordinateurs Migen"}]'::jsonb) where path = '/preuves/voit-grand-est/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"Disponibilité accrue","libelle":"Les lignes de production tournent davantage."},{"valeur":"Moins d''incidents récurrents","libelle":"Les pannes qui revenaient faute de traitement de fond ont reculé."},{"valeur":"Montée en compétence des équipes internes","libelle":"Elle vient de la collaboration quotidienne avec le technicien Migen."},{"valeur":"Plan de maintenance amélioré en continu","libelle":"Il reste aligné sur les standards VOIT."}]'::jsonb) where path = '/preuves/voit-grand-est/';
